# This code has been fully generated by an AI.
import ipaddress
import json

from hebocon import discovery, network
from hebocon.network import Adapter

WLAN = Adapter("WLAN", "192.168.0.98", "255.255.255.0", True)
WSL = Adapter("vEthernet (WSL)", "172.27.48.1", "255.255.240.0", True)
ETH_DOWN = Adapter("Ethernet", "192.168.10.58", "255.255.255.0", False)


def test_remembered_prefers_name_then_ip():
    moved = Adapter("WLAN", "192.168.0.120", "255.255.255.0", True)
    assert network.remembered([moved, WSL], {"name": "WLAN", "ip": "192.168.0.98"}) == moved
    assert network.remembered([WSL], {"name": "alt", "ip": "172.27.48.1"}) == WSL


def test_remembered_ignores_disconnected():
    assert network.remembered([ETH_DOWN, WLAN], {"name": "Ethernet"}) is None


def test_choose_without_tty_uses_remembered(tmp_path, monkeypatch):
    path = tmp_path / "network.json"
    path.write_text(json.dumps({"name": "vEthernet (WSL)", "ip": "x"}))
    monkeypatch.setattr(network, "adapters", lambda: [WLAN, WSL, ETH_DOWN])
    monkeypatch.setattr("sys.stdin", None)
    assert network.choose(path) == WSL


def test_choose_falls_back_to_first_connected_and_saves(tmp_path, monkeypatch):
    path = tmp_path / "network.json"
    path.write_text(json.dumps({"name": "Ethernet", "ip": "192.168.10.58"}))
    monkeypatch.setattr(network, "adapters", lambda: [WLAN, WSL, ETH_DOWN])
    monkeypatch.setattr("sys.stdin", None)
    assert network.choose(path) == WLAN
    assert json.loads(path.read_text())["name"] == "WLAN"


def test_choose_none_without_connected_adapter(tmp_path, monkeypatch):
    monkeypatch.setattr(network, "adapters", lambda: [ETH_DOWN])
    assert network.choose(tmp_path / "network.json") is None


def test_discovery_answers_only_selected_subnet():
    subnet = WLAN.subnet
    own = {"192.168.0.98", "172.27.48.1"}
    assert discovery.allowed("192.168.0.42", subnet, own)
    assert discovery.allowed("127.0.0.1", subnet, own)
    assert discovery.allowed("172.27.48.1", subnet, own)
    assert not discovery.allowed("172.27.48.7", subnet, own)
    assert discovery.allowed("10.0.0.1", None, set())
    assert subnet == ipaddress.ip_network("192.168.0.0/24")
